# Simulate HDFC direction cleanup
import pandas as pd
import re

def py_extract(description, pat, index):
    res = description.str.extract(pat=pat, flags=re.IGNORECASE).get(index)
    if res is None:
        return pd.Series(['']*len(description))
    res = res.fillna('')
    return res

# cases
names = pd.Series(['To Rajesh Kumar', 'From Priya Sharma', 'By Amit Shah', 'Trf To John Doe', 'Trf John Doe', 'Paid To Alice'])
# L253-257 logic
for n in names:
    s = pd.Series([n])
    if bool(s.str.contains('^By', case=False).iloc[0]):
        out = s.replace(to_replace='^By ', value='', regex=True).iloc[0]
    elif bool(s.str.contains('^Trn?f To |^Fnf To |^Paid To |^Fund Trf To|^Amt Paid To', case=False).iloc[0]):
        out = py_extract(s, ' To (.*)', 0).iloc[0]
    elif bool(s.str.contains('^Trf ', case=False).iloc[0]):
        out = py_extract(s, 'Trf (.*)', 0).iloc[0]
    else:
        out = 'UNCHANGED:'+n
    print(repr(n), '->', repr(out))
"
